sys_script_include.script:
var UiActionUtil = Class.create();
UiActionUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	//For Create Email
    getEmails: function() {
        var query = this.getParameter('sysparm_value');
        var gr = new GlideRecord("customer_contact");
        gr.addEncodedQuery(query);
        gr.query();
        gs.info('nice test: ' + gr.getEncodedQuery());
        var arr = [];
        while (gr.next()) {
            arr.push(gr.u_email_address.toString());
        }
        return arr.join(',');
    },

    type: 'UiActionUtil'
});
